import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Datenschutzoptionen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy-choices.md","filePath":"de/guide/privacy-choices.md","lastUpdated":1793173149000}`),a={name:`de/guide/privacy-choices.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="datenschutzoptionen" tabindex="-1">Datenschutzoptionen <a class="header-anchor" href="#datenschutzoptionen" aria-label="Permalink to “Datenschutzoptionen”">​</a></h1><p>Sudoku ist eine Offline-First-App mit minimalem Datenumgang. Diese Seite erläutert Ihre Datenschutzoptionen und wie Sie Ihre Daten kontrollieren.</p><h2 id="ihre-daten-bleiben-standardmaßig-auf-ihrem-gerat" tabindex="-1">Ihre Daten bleiben standardmäßig auf Ihrem Gerät <a class="header-anchor" href="#ihre-daten-bleiben-standardmaßig-auf-ihrem-gerat" aria-label="Permalink to “Ihre Daten bleiben standardmäßig auf Ihrem Gerät”">​</a></h2><ul><li>Alle Spieldaten — Einstellungen, Spielstand, Notizen und Statistiken — werden standardmäßig lokal auf Ihrem Gerät gespeichert.</li><li>Das Kernspiel benötigt keinerlei Netzwerkzugriff.</li><li>Es gibt keine Werbung, keine Analyse und kein Tracking.</li></ul><h2 id="optionale-cloud-funktionen" tabindex="-1">Optionale Cloud-Funktionen <a class="header-anchor" href="#optionale-cloud-funktionen" aria-label="Permalink to “Optionale Cloud-Funktionen”">​</a></h2><h3 id="icloud-synchronisierung" tabindex="-1">iCloud-Synchronisierung <a class="header-anchor" href="#icloud-synchronisierung" aria-label="Permalink to “iCloud-Synchronisierung”">​</a></h3><p>Wenn Sie die iCloud-Synchronisierung aktivieren:</p><ul><li>Daten werden ausschließlich mit <strong>Ihrem persönlichen iCloud-Account</strong> synchronisiert — nicht mit einem von uns kontrollierten Server.</li><li>Apples CloudKit übernimmt die Verschlüsselung bei der Übertragung und im Ruhezustand.</li><li>Sie können dies jederzeit deaktivieren: Einstellungen → [Ihr Name] → iCloud → Apps, die iCloud verwenden → Sudoku ausschalten.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Wenn Sie Game Center nutzen:</p><ul><li>Ranglistenpunkte können öffentlich unter Ihrem Game-Center-Anzeigenamen erscheinen.</li><li>Der Erfolgsfortschritt wird von Game Center erfasst.</li><li>Sie können dies deaktivieren, indem Sie sich in den Einstellungen bei Game Center abmelden.</li></ul><h2 id="die-einzige-nicht-cloud-netzwerkfunktion-„weitere-apps" tabindex="-1">Die einzige Nicht-Cloud-Netzwerkfunktion: „Weitere Apps“ <a class="header-anchor" href="#die-einzige-nicht-cloud-netzwerkfunktion-„weitere-apps" aria-label="Permalink to “Die einzige Nicht-Cloud-Netzwerkfunktion: „Weitere Apps“”">​</a></h2><p>Der einzige weitere Netzwerkzugriff ist der optionale Bereich <strong>„Weitere Apps“</strong> in den Einstellungen, der eine Liste weiterer Apps abruft. Diese Funktion:</p><ul><li>sendet keine personenbezogenen Daten — sie ruft lediglich eine Liste von App-Namen und Links ab.</li><li>kann vollständig ignoriert werden, ohne das Spiel zu beeinträchtigen.</li><li>verfolgt Sie nicht und speichert keine Kennungen.</li></ul><h2 id="ihre-daten-loschen" tabindex="-1">Ihre Daten löschen <a class="header-anchor" href="#ihre-daten-loschen" aria-label="Permalink to “Ihre Daten löschen”">​</a></h2><p>So entfernen Sie alle App-Daten von Ihrem Gerät:</p><ul><li><strong>iPhone/iPad</strong>: Löschen Sie die App und installieren Sie sie neu</li><li><strong>Mac</strong>: Beenden Sie Sudoku und entfernen Sie anschließend den Container:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><p>So löschen Sie zusätzlich die mit iCloud synchronisierten Daten:</p><ol><li>Öffnen Sie <strong>Einstellungen → [Ihr Name] → iCloud → Account-Speicher verwalten</strong></li><li>Suchen Sie Sudoku in der App-Liste</li><li>Tippen Sie auf <strong>Daten löschen</strong></li></ol><p>Dadurch werden alle Einstellungen, Statistiken, Spielstände und Fortschritte bei täglichen Herausforderungen dauerhaft aus iCloud gelöscht.</p><h2 id="kein-tracking-keine-werbung" tabindex="-1">Kein Tracking, keine Werbung <a class="header-anchor" href="#kein-tracking-keine-werbung" aria-label="Permalink to “Kein Tracking, keine Werbung”">​</a></h2><p>Sudoku enthält keine Werbung, keine Analyse, keine Tracking-Pixel und keine Integrationen zur Datenweitergabe an Dritte. Die App benötigt für das Spielen keinen Netzwerkzugriff.</p><h2 id="ubersicht-der-datenschutzanfragen" tabindex="-1">Übersicht der Datenschutzanfragen <a class="header-anchor" href="#ubersicht-der-datenschutzanfragen" aria-label="Permalink to “Übersicht der Datenschutzanfragen”">​</a></h2><table tabindex="0"><thead><tr><th>Anfrage</th><th>Erforderlich?</th><th>Funktion</th></tr></thead><tbody><tr><td>Lokale Speicherung</td><td>Ja (automatisch)</td><td>Speichert Spieldaten auf dem Gerät</td></tr><tr><td>iCloud-Synchronisierung</td><td>Optional</td><td>Synchronisiert Daten über CloudKit zwischen Ihren Geräten</td></tr><tr><td>Game Center</td><td>Optional</td><td>Ranglisten &amp; Erfolge</td></tr><tr><td>Netzwerk („Weitere Apps“)</td><td>Optional</td><td>Ruft die Liste weiterer Apps ab</td></tr></tbody></table><p>Da keine personenbezogenen Daten erhoben oder an von uns kontrollierte Server übertragen werden, gibt es keine zentrale Datenbank, auf die zugegriffen werden könnte oder die gelöscht oder übertragen werden müsste. Alle Daten liegen entweder lokal oder werden von Apples Diensten (iCloud/Game Center) verwaltet.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to “Kontakt”">​</a></h2><p>Wenn Sie Fragen zu diesem Ablauf haben, eröffnen Sie ein Issue unter <code>https://github.com/sudoku-pro/sudoku-site/issues</code> oder schreiben Sie eine E-Mail an <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};